[{"order":1,"type":"heading","text":"Spring MVC with Spring Boot: Building RESTful APIs and Web Applications"},{"order":2,"type":"paragraph","text":"This tutorial guides you through building RESTful APIs and web applications using Spring MVC with Spring Boot. Spring Boot simplifies the configuration and setup process, allowing you to focus on developing your application's logic. We'll cover essential concepts, provide code examples, and explain best practices."},{"order":3,"type":"heading","text":"Prerequisites"},{"order":4,"type":"bullet_point","text":"Java Development Kit (JDK) 8 or higher"},{"order":5,"type":"bullet_point","text":"Maven or Gradle build tool"},{"order":6,"type":"bullet_point","text":"Integrated Development Environment (IDE) like IntelliJ IDEA, Eclipse, or Visual Studio Code"},{"order":7,"type":"heading","text":"Setting Up a Spring Boot Project"},{"order":8,"type":"paragraph","text":"The easiest way to start a Spring Boot project is using Spring Initializr (start.spring.io).  This web tool allows you to select your project dependencies and generate a basic project structure.  For this tutorial, we'll create a Maven project with the following dependencies:"},{"order":9,"type":"bullet_point","text":"Spring Web (for Spring MVC and REST support)"},{"order":10,"type":"bullet_point","text":"Spring Data JPA (for database interaction, optional for REST API only)"},{"order":11,"type":"bullet_point","text":"H2 Database (an in-memory database for development, optional for REST API only)"},{"order":12,"type":"bullet_point","text":"Lombok (for reducing boilerplate code)"},{"order":13,"type":"paragraph","text":"Generate the project and import it into your IDE."},{"order":14,"type":"heading","text":"Building a RESTful API"},{"order":15,"type":"subheading","text":"Creating a Model"},{"order":16,"type":"paragraph","text":"Let's start by defining a simple model class, `Book`:"},{"order":17,"type":"code","text":"package com.example.demo.model;

import lombok.Data;
import javax.persistence.Entity;
import javax.persistence.GeneratedValue;
import javax.persistence.GenerationType;
import javax.persistence.Id;

@Data
@Entity
public class Book {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;
    private String title;
    private String author;
}"},{"order":18,"type":"paragraph","text":"The `@Data` annotation from Lombok automatically generates getters, setters, `equals()`, `hashCode()`, and `toString()` methods. The `@Entity` annotation marks this class as a JPA entity, and the `@Id` and `@GeneratedValue` annotations define the primary key."},{"order":19,"type":"subheading","text":"Creating a Repository"},{"order":20,"type":"paragraph","text":"Next, create a repository interface to interact with the database:"},{"order":21,"type":"code","text":"package com.example.demo.repository;

import com.example.demo.model.Book;
import org.springframework.data.jpa.repository.JpaRepository;

public interface BookRepository extends JpaRepository<Book, Long> {
}
"},{"order":22,"type":"paragraph","text":"The `JpaRepository` interface provides basic CRUD (Create, Read, Update, Delete) operations. Spring Data JPA automatically generates the implementation for this interface."},{"order":23,"type":"subheading","text":"Creating a Controller"},{"order":24,"type":"paragraph","text":"Now, create a controller to handle incoming HTTP requests:"},{"order":25,"type":"code","text":"package com.example.demo.controller;

import com.example.demo.model.Book;
import com.example.demo.repository.BookRepository;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import java.util.List;

@RestController
@RequestMapping("/api/books")
public class BookController {

    @Autowired
    private BookRepository bookRepository;

    @GetMapping
    public List<Book> getAllBooks() {
        return bookRepository.findAll();
    }

    @GetMapping("/{id}")
    public ResponseEntity<Book> getBookById(@PathVariable Long id) {
        return bookRepository.findById(id)
                .map(book -> new ResponseEntity<>(book, HttpStatus.OK))
                .orElse(new ResponseEntity<>(HttpStatus.NOT_FOUND));
    }

    @PostMapping
    public ResponseEntity<Book> createBook(@RequestBody Book book) {
        Book savedBook = bookRepository.save(book);
        return new ResponseEntity<>(savedBook, HttpStatus.CREATED);
    }

    @PutMapping("/{id}")
    public ResponseEntity<Book> updateBook(@PathVariable Long id, @RequestBody Book book) {
        return bookRepository.findById(id)
                .map(existingBook -> {
                    book.setId(id);
                    Book updatedBook = bookRepository.save(book);
                    return new ResponseEntity<>(updatedBook, HttpStatus.OK);
                })
                .orElse(new ResponseEntity<>(HttpStatus.NOT_FOUND));
    }

    @DeleteMapping("/{id}")
    public ResponseEntity<Void> deleteBook(@PathVariable Long id) {
        return bookRepository.findById(id)
                .map(existingBook -> {
                    bookRepository.deleteById(id);
                    return new ResponseEntity<Void>(HttpStatus.NO_CONTENT);
                })
                .orElse(new ResponseEntity<>(HttpStatus.NOT_FOUND));
    }
}"},{"order":26,"type":"paragraph","text":"Let's break down the code:"},{"order":27,"type":"bullet_point","text":"`@RestController`:  Marks the class as a controller and indicates that methods should return the response directly instead of a view name."},{"order":28,"type":"bullet_point","text":"`@RequestMapping("/api/books")`:  Maps all requests with the `/api/books` path to this controller."},{"order":29,"type":"bullet_point","text":"`@Autowired`:  Injects the `BookRepository` dependency."},{"order":30,"type":"bullet_point","text":"`@GetMapping`: Maps HTTP GET requests to specific handler methods."},{"order":31,"type":"bullet_point","text":"`@PostMapping`: Maps HTTP POST requests to specific handler methods."},{"order":32,"type":"bullet_point","text":"`@PutMapping`: Maps HTTP PUT requests to specific handler methods."},{"order":33,"type":"bullet_point","text":"`@DeleteMapping`: Maps HTTP DELETE requests to specific handler methods."},{"order":34,"type":"bullet_point","text":"`@PathVariable`:  Extracts values from the URI path."},{"order":35,"type":"bullet_point","text":"`@RequestBody`:  Binds the request body to a method parameter."},{"order":36,"type":"paragraph","text":"The controller defines endpoints for retrieving all books, retrieving a book by ID, creating a new book, updating an existing book, and deleting a book."},{"order":37,"type":"heading","text":"Building a Web Application (Optional)"},{"order":38,"type":"paragraph","text":"To build a web application, you'll typically use a templating engine like Thymeleaf.  First, add the Thymeleaf dependency to your `pom.xml` or `build.gradle` file."},{"order":39,"type":"paragraph","text":"Then, create a controller that returns view names:"},{"order":40,"type":"code","text":"package com.example.demo.controller;

import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.GetMapping;

@Controller
public class WebController {

    @GetMapping("/")
    public String home(Model model) {
        model.addAttribute("message", "Hello, Thymeleaf!");
        return "home"; // Returns the name of the Thymeleaf template (home.html)
    }
}"},{"order":41,"type":"paragraph","text":"Create a Thymeleaf template named `home.html` in the `src/main/resources/templates` directory:"},{"order":42,"type":"code","text":"<!DOCTYPE html>
<html xmlns:th="http://www.thymeleaf.org">
<head>
    <title>Thymeleaf Example</title>
</head>
<body>
    <h1 th:text="${message}"></h1>
</body>
</html>"},{"order":43,"type":"paragraph","text":"This template displays the message passed from the controller."},{"order":44,"type":"heading","text":"Running the Application"},{"order":45,"type":"paragraph","text":"Run the Spring Boot application from your IDE or using the command line:"},{"order":46,"type":"code","text":"./mvnw spring-boot:run   # For Maven
./gradlew bootRun       # For Gradle"},{"order":47,"type":"paragraph","text":"For the REST API, you can use tools like Postman or curl to test the endpoints. For the web application, access the application in your browser (usually at `http://localhost:8080`)."},{"order":48,"type":"heading","text":"Conclusion"},{"order":49,"type":"paragraph","text":"This tutorial provided a basic introduction to building RESTful APIs and web applications with Spring MVC and Spring Boot.  You can expand upon this foundation by adding features like authentication, authorization, validation, and more sophisticated data handling."}]
